class TestStatus(str, Enum):
    PASS = "PASS"
    WARN = "WARN"
    FAIL = "FAIL"


@dataclass
class TestResult:
    test_id: str
    name: str
    status: TestStatus
    summary: str
    metrics: Dict[str, Any]
    recommendations: List[str]


@dataclass
class ExecutionReport:
    execution_id: str
    test_plan_id: str
    global_status: TestStatus
    results: List[TestResult]


class IntentSpec(BaseModel):
    intent: Literal["validate_dataset", "execute_test_plan", "run_regression", "review_fixed_defect", "unknown"] = "validate_dataset"
    artifact_type: Literal["dataset", "model", "pipeline", "unknown"] = "dataset"
    requested_tests: List[Literal["nulls", "duplicates", "data_types", "outliers"]] = Field(default_factory=list)
    excluded_columns: List[str] = Field(default_factory=list)
    critical_columns: List[str] = Field(default_factory=list)
    max_null_ratio_default: Optional[float] = None
    max_duplicate_ratio: Optional[float] = None
    max_outlier_ratio: Optional[float] = None
    needs_artifact: bool = True
    user_goal_summary: str = ""


DEFAULT_INTENT = IntentSpec(
    requested_tests=["nulls", "duplicates", "data_types", "outliers"],
    user_goal_summary="Validar la calidad básica de un dataset."
)


def filter_excluded_columns(df: pd.DataFrame, excluded_columns: List[str]) -> pd.DataFrame:
    valid_exclusions = [col for col in excluded_columns if col in df.columns]
    return df.drop(columns=valid_exclusions) if valid_exclusions else df


def check_nulls(df: pd.DataFrame, critical_columns: Optional[List[str]] = None, max_null_ratio_default: float = 0.05) -> TestResult:
    critical_columns = critical_columns or []
    null_ratio_by_column = df.isna().mean().sort_values(ascending=False)
    global_null_ratio = float(df.isna().sum().sum() / (df.shape[0] * df.shape[1])) if df.size > 0 else 0.0

    failed_critical = [col for col in critical_columns if col in df.columns and null_ratio_by_column[col] > 0.0]
    failed_default = [col for col, ratio in null_ratio_by_column.items() if col not in critical_columns and ratio > max_null_ratio_default + 0.05]
    warned_default = [col for col, ratio in null_ratio_by_column.items() if col not in critical_columns and max_null_ratio_default < ratio <= max_null_ratio_default + 0.05]

    if failed_critical:
        status = TestStatus.FAIL
        summary = f"Columnas críticas con valores nulos: {', '.join(failed_critical)}."
    elif failed_default:
        status = TestStatus.FAIL
        summary = f"Columnas que exceden claramente el umbral de nulos: {', '.join(failed_default)}."
    elif warned_default:
        status = TestStatus.WARN
        summary = f"Columnas que superan ligeramente el umbral de nulos: {', '.join(warned_default)}."
    else:
        status = TestStatus.PASS
        summary = "Todas las columnas cumplen los umbrales de nulos definidos."

    return TestResult(
        test_id="TST-Nulls-001",
        name="Nulos",
        status=status,
        summary=summary,
        metrics={
            "global_null_ratio": round(global_null_ratio, 4),
            "null_ratio_by_column": null_ratio_by_column.round(4).to_dict(),
        },
        recommendations=["Revisar ingesta.", "Valorar imputación o descarte según impacto funcional."],
    )


def check_duplicates(df: pd.DataFrame, max_duplicate_ratio: float = 0.0) -> TestResult:
    duplicate_count = int(df.duplicated().sum())
    duplicate_ratio = float(duplicate_count / len(df)) if len(df) > 0 else 0.0

    if duplicate_ratio == 0 or duplicate_ratio <= max_duplicate_ratio:
        status = TestStatus.PASS
        summary = "No se detectan duplicados fuera del umbral."
    elif duplicate_ratio <= max_duplicate_ratio + 0.02:
        status = TestStatus.WARN
        summary = "Se detectan duplicados puntuales que requieren revisión."
    else:
        status = TestStatus.FAIL
        summary = "Se detectan duplicados por encima del umbral permitido."

    return TestResult(
        test_id="TST-Duplicates-002",
        name="Duplicados",
        status=status,
        summary=summary,
        metrics={"duplicate_count": duplicate_count, "duplicate_ratio": round(duplicate_ratio, 4)},
        recommendations=["Revisar claves de unicidad.", "Eliminar duplicados no justificados."],
    )


def check_data_types(df: pd.DataFrame) -> TestResult:
    dtypes = {col: str(dtype) for col, dtype in df.dtypes.items()}
    object_columns = [col for col, dtype in dtypes.items() if dtype == "object"]
    status = TestStatus.WARN if object_columns else TestStatus.PASS
    summary = "Se detectan columnas tipo object/texto." if object_columns else "Tipos iniciales sin incidencias relevantes."

    return TestResult(
        test_id="TST-DataType-003",
        name="Tipos",
        status=status,
        summary=summary,
        metrics={
            "row_count": int(df.shape[0]),
            "column_count": int(df.shape[1]),
            "object_columns": object_columns,
            "dtypes": dtypes
        },
        recommendations=["Definir esquema esperado.", "Normalizar fechas, categorías y variables booleanas."],
    )


def check_outliers_iqr(df: pd.DataFrame, max_outlier_ratio: float = 0.10) -> TestResult:
    numeric_df = df.select_dtypes(include=[np.number])
    if numeric_df.empty:
        return TestResult("TST-Outliers-004", "Outliers", TestStatus.WARN, "No hay columnas numéricas.", {"numeric_columns": []}, ["Revisar dataset."])

    outlier_ratios: Dict[str, float] = {}
    for col in numeric_df.columns:
        q1 = numeric_df[col].quantile(0.25)
        q3 = numeric_df[col].quantile(0.75)
        iqr = q3 - q1
        if iqr == 0 or pd.isna(iqr):
            outlier_ratios[col] = 0.0
            continue
        lower = q1 - 1.5 * iqr
        upper = q3 + 1.5 * iqr
        outlier_ratios[col] = float(((numeric_df[col] < lower) | (numeric_df[col] > upper)).mean())

    failing_cols = [col for col, ratio in outlier_ratios.items() if ratio > max_outlier_ratio]
    warning_cols = [col for col, ratio in outlier_ratios.items() if 0 < ratio <= max_outlier_ratio]

    if failing_cols:
        status = TestStatus.FAIL
        summary = f"Outliers por encima del umbral en: {', '.join(failing_cols)}."
    elif warning_cols:
        status = TestStatus.WARN
        summary = f"Outliers moderados en: {', '.join(warning_cols)}."
    else:
        status = TestStatus.PASS
        summary = "No se detectan outliers relevantes."

    return TestResult(
        test_id="TST-Outliers-004",
        name="Outliers",
        status=status,
        summary=summary,
        metrics={"method": "IQR", "outlier_ratio_by_column": {k: round(v, 4) for k, v in outlier_ratios.items()}},
        recommendations=["Revisar valores extremos.", "Distinguir error de captura frente a caso válido."],
    )


def aggregate_status(results: List[TestResult]) -> TestStatus:
    statuses = [r.status for r in results]
    if TestStatus.FAIL in statuses:
        return TestStatus.FAIL
    if TestStatus.WARN in statuses:
        return TestStatus.WARN
    return TestStatus.PASS


def execute_selected_tests(df: pd.DataFrame, intent: IntentSpec) -> ExecutionReport:
    requested = intent.requested_tests or ["nulls", "duplicates", "data_types", "outliers"]
    df_eval = filter_excluded_columns(df, intent.excluded_columns)
    results: List[TestResult] = []

    if "nulls" in requested:
        results.append(check_nulls(df_eval, intent.critical_columns, intent.max_null_ratio_default or 0.05))
    if "duplicates" in requested:
        results.append(check_duplicates(df_eval, intent.max_duplicate_ratio or 0.0))
    if "data_types" in requested:
        results.append(check_data_types(df_eval))
    if "outliers" in requested:
        results.append(check_outliers_iqr(df_eval, intent.max_outlier_ratio or 0.10))

    return ExecutionReport(
        execution_id=f"EXEC-{uuid.uuid4().hex[:8].upper()}",
        test_plan_id="TP-DATA-QUALITY-DYNAMIC-001",
        global_status=aggregate_status(results),
        results=results,
    )


def parse_percentage_to_ratio(text: str, default: Optional[float] = None) -> Optional[float]:
    match = re.search(r"(\d+(?:[.,]\d+)?)\s*%", text)
    if not match:
        return default
    return float(match.group(1).replace(",", ".")) / 100.0


def fallback_intent_parser(user_message: str) -> IntentSpec:
    msg = user_message.lower()

    tests: List[str] = []
    if "nulo" in msg or "null" in msg or "missing" in msg:
        tests.append("nulls")
    if "duplic" in msg:
        tests.append("duplicates")
    if "tipo" in msg or "schema" in msg or "esquema" in msg:
        tests.append("data_types")
    if "outlier" in msg or "atípico" in msg or "atipico" in msg or "extremo" in msg:
        tests.append("outliers")
    if not tests:
        tests = ["nulls", "duplicates", "data_types", "outliers"]

    intent = "validate_dataset"
    if "regresión" in msg or "regresion" in msg:
        intent = "run_regression"
    elif "defecto" in msg or "bug" in msg or "incidencia" in msg:
        intent = "review_fixed_defect"
    elif "plan" in msg:
        intent = "execute_test_plan"

    excluded_columns: List[str] = []
    ignore_match = re.search(r"(?:ignora|excluye|sin)\s+(?:la columna|columna)?\s*([a-zA-Z0-9_,\s]+)", msg)
    if ignore_match:
        raw = ignore_match.group(1)
        excluded_columns = [c.strip() for c in re.split(r",| y ", raw) if c.strip()]

    critical_columns: List[str] = []
    for col in ["occupancy", "temperature", "target", "co2", "temperatura"]:
        if f"{col} como columna crítica" in msg or f"{col} como columna critica" in msg:
            critical_columns.append(col)

    return IntentSpec(
        intent=intent,  # type: ignore[arg-type]
        requested_tests=tests,  # type: ignore[list-item]
        excluded_columns=excluded_columns,
        critical_columns=critical_columns,
        max_null_ratio_default=parse_percentage_to_ratio(msg, None),
        user_goal_summary=user_message,
    )


def interpret_user_intent(user_message: str, model_name: str) -> IntentSpec:
    if not LANGCHAIN_OPENAI_AVAILABLE:
        return fallback_intent_parser(user_message)

    try:
        llm = ChatOpenAI(model=model_name, temperature=0)
        structured_llm = llm.with_structured_output(IntentSpec)
        prompt = f"""
Eres un intérprete de instrucciones para QABot, un asistente QA del ciclo del dato.
Convierte la petición del usuario en una especificación estructurada.

Reglas:
- No inventes tests fuera de: nulls, duplicates, data_types, outliers.
- Si el usuario pide validar un dataset en general o revisar si es apto para entrenar, incluye todos los tests.
- Si pide ignorar columnas, inclúyelas en excluded_columns.
- Si indica columnas críticas, inclúyelas en critical_columns.
- Si expresa umbrales como porcentajes, conviértelos a ratios entre 0 y 1.
- Si la intención no está clara, usa validate_dataset.

Petición:
{user_message}
"""
        result = structured_llm.invoke(prompt)
        return result if isinstance(result, IntentSpec) else IntentSpec.model_validate(result)
    except Exception:
        return fallback_intent_parser(user_message)


class QAState(TypedDict, total=False):
    user_message: str
    df: Any
    model_name: str
    intent: IntentSpec
    report: ExecutionReport
    assistant_message: str
    error: str


def node_detect_intent(state: QAState) -> QAState:
    state["intent"] = interpret_user_intent(state["user_message"], state.get("model_name", "gpt-4.1-mini"))
    return state


def node_check_artifact(state: QAState) -> QAState:
    if state.get("df") is None:
        state["error"] = "Necesito que me pases el dataset en formato CSV para poder empezar la revisión."
    return state


def node_execute_tests(state: QAState) -> QAState:
    if state.get("error"):
        return state
    df = state["df"]
    if not isinstance(df, pd.DataFrame):
        state["error"] = "El artefacto cargado no es un DataFrame válido."
        return state
    state["report"] = execute_selected_tests(df, state.get("intent", DEFAULT_INTENT))
    return state


def node_build_response(state: QAState) -> QAState:
    if state.get("error"):
        state["assistant_message"] = html.escape(state["error"])
        return state

    intent = state.get("intent", DEFAULT_INTENT)
    report = state["report"]
    selected = ", ".join(intent.requested_tests or [])

    lines = [
        f"He interpretado la solicitud como <b>{html.escape(intent.intent)}</b>.",
        f"Validaciones seleccionadas: <b>{html.escape(selected)}</b>.",
    ]

    if intent.excluded_columns:
        lines.append(f"Columnas excluidas: <b>{html.escape(', '.join(intent.excluded_columns))}</b>.")
    if intent.critical_columns:
        lines.append(f"Columnas críticas: <b>{html.escape(', '.join(intent.critical_columns))}</b>.")

    lines.append(f"Resultado global: <b>{html.escape(report.global_status.value)}</b>.")
    state["assistant_message"] = "<br/>".join(lines)
    return state


def build_graph():
    graph = StateGraph(QAState)
    graph.add_node("detect_intent", node_detect_intent)
    graph.add_node("check_artifact", node_check_artifact)
    graph.add_node("execute_tests", node_execute_tests)
    graph.add_node("build_response", node_build_response)
    graph.set_entry_point("detect_intent")
    graph.add_edge("detect_intent", "check_artifact")
    graph.add_edge("check_artifact", "execute_tests")
    graph.add_edge("execute_tests", "build_response")
    graph.add_edge("build_response", END)
    return graph.compile()


def status_class(status: TestStatus) -> str:
    return {
        TestStatus.PASS: "status-pass",
        TestStatus.WARN: "status-warn",
        TestStatus.FAIL: "status-fail",
    }[status]


def status_icon(status: TestStatus) -> str:
    return {
        TestStatus.PASS: "✓",
        TestStatus.WARN: "!",
        TestStatus.FAIL: "×",
    }[status]


def status_label(status: TestStatus) -> str:
    return f'<span class="{status_class(status)}">{status_icon(status)} {status.value}</span>'


def metric_bar(label: str, value: float) -> str:
    value = max(0, min(100, value))
    return (
        f'<div class="metric-row">'
        f'<div>{html.escape(label)}</div>'
        f'<div class="track"><div class="fill" style="width:{value}%;"></div></div>'
        f'<div>{value:.1f}%</div>'
        f'</div>'
    )


def render_message(role: str, content: str, timestamp: str) -> str:
    safe_time = html.escape(timestamp)
    if role == "user":
        safe_content = html.escape(content)
        return (
            f'<div class="message-row user">'
            f'<div class="bubble user">{safe_content}<div class="msg-time">{safe_time} ✓✓</div></div>'
            f'</div>'
        )

    # Assistant content can contain our controlled <b>/<br/> tags.
    return (
        f'<div class="message-row">'
        f'<div class="avatar">🤖</div>'
        f'<div class="bubble">{content}<div class="msg-time">{safe_time}</div></div>'
        f'</div>'
    )


def render_chat_html(messages: List[Dict[str, str]]) -> str:
    if not messages:
        inner = (
            '<div class="empty-chat">'
            '<div class="empty-icon">•••</div>'
            '<div class="empty-title">Inicia una conversación</div>'
            '<div class="empty-sub">Escribe tu mensaje para comenzar</div>'
            '</div>'
        )
    else:
        inner = "".join(render_message(m["role"], m["content"], m["timestamp"]) for m in messages)

    return (
        '<div class="center-card">'
        '<div class="chat-header">'
        '<div class="bot-icon">🤖</div>'
        '<div>'
        '<div class="title-main">QABOT</div>'
        '<div class="title-sub">ASISTENTE AGÉNTICO DE CALIDAD</div>'
        '<div class="title-caption">Chatbot implementado con Arquitectura Agéntica</div>'
        '</div>'
        '<div class="robot-stage"><div class="robot">🤖</div></div>'
        '</div>'
        f'<div class="chat-box">{inner}</div>'
        '</div>'
    )


def report_to_json(report: ExecutionReport) -> str:
    return json.dumps(asdict(report), ensure_ascii=False, indent=2, default=str)


def render_last_run(report: Optional[ExecutionReport]) -> str:
    if report is None:
        return (
            '<div class="last-run">'
            '<div class="panel-title" style="font-size:15px;margin-bottom:6px;">▣ ÚLTIMA EJECUCIÓN</div>'
            '<div style="color:var(--muted);font-size:12px;line-height:1.35;">'
            'Todavía no hay resultados. Carga un CSV y solicita una validación.'
            '</div>'
            '</div>'
        )

    rows = []
    for r in report.results:
        rows.append(
            '<div class="result-line">'
            f'<div>{html.escape(r.name)}</div>'
            f'<div>{status_label(r.status)}</div>'
            '</div>'
        )

    return (
        '<div class="last-run">'
        '<div class="panel-title" style="font-size:15px;margin-bottom:6px;">▣ ÚLTIMA EJECUCIÓN</div>'
        '<div style="font-size:12px;margin-bottom:6px;">'
        f'Global: {status_label(report.global_status)}<br/>'
        f'<span style="color:var(--muted);">ID: {html.escape(report.execution_id)}</span>'
        '</div>'
        f'{"".join(rows)}'
        '</div>'
    )


def render_history(history: List[tuple[str, str, str]]) -> str:
    rows = []
    for icon, title, date in history[:4]:
        rows.append(
            '<div class="history-item">'
            f'<div class="hist-icon">{html.escape(icon)}</div>'
            '<div>'
            f'<div class="hist-title">{html.escape(title)}</div>'
            f'<div class="hist-date">{html.escape(date)}<span class="badge">Completado</span></div>'
            '</div>'
            '<div class="check">✓</div>'
            '</div>'
        )

    return (
        '<div class="history-card">'
        f'{"".join(rows)}'
        '</div>'
    )


def init_state() -> None:
    if "messages" not in st.session_state:
        st.session_state.messages = []
    if "last_report" not in st.session_state:
        st.session_state.last_report = None
    if "last_intent" not in st.session_state:
        st.session_state.last_intent = None
    if "history" not in st.session_state:
        st.session_state.history = [
            ("▰", "Proyecto D - Nulos", "24/05/2024 10:35"),
            ("▣", "Proyecto C - Duplicados", "23/05/2024 16:20"),
            ("T", "Proyecto B - Tipos de datos", "22/05/2024 11:10"),
            ("↗", "Proyecto A - Valores atípicos", "21/05/2024 09:45"),
        ]


def reset_conversation() -> None:
    st.session_state.messages = []
    st.session_state.last_report = None
    st.session_state.last_intent = None


def main() -> None:
    st.set_page_config(page_title="QABot", layout="wide", initial_sidebar_state="collapsed")
    st.markdown(CSS, unsafe_allow_html=True)
    init_state()

    app = build_graph()
    left, center, right = st.columns([0.18, 0.57, 0.25], gap="small")

    with left:
        st.markdown(
            """
            <div class="neon-panel left-panel">
                <div class="panel-title"><div class="info-icon">i</div> LIMITACIONES</div>
                <div class="limit-box">
                    <div class="limit-top">
                        <div class="bot-icon-small">🤖</div>
                        <div style="font-weight:800;color:#b84cff;font-size:15px;">
                            QABot en fase<br/>de mejora
                        </div>
                    </div>
                    <p class="limit-lead">
                        Soy QABot, un asistente agéntico de calidad impulsado por arquitectura agéntica.
                    </p>
                    <div class="divider"></div>
                    <ul class="limit-list">
                        <li>Puedo cometer errores.</li>
                        <li>Mi conocimiento puede estar desactualizado.</li>
                        <li>No tengo acceso en tiempo real a internet.</li>
                        <li>No realizo acciones externas ni accedo a sistemas privados.</li>
                        <li>Estoy en constante aprendizaje para ofrecerte mejores respuestas.</li>
                    </ul>
                    <div class="divider"></div>
                    <p class="thanks">★ Gracias por tu comprensión y por ayudarme a mejorar cada día.</p>
                </div>
                <div class="new-session-box">
                    <div class="panel-title" style="font-size:14px;margin-bottom:8px;">NUEVA CONVERSACIÓN</div>
                    <div style="height:42px;"></div>
                </div>
            </div>
            """,
            unsafe_allow_html=True,
        )
        if st.button("＋  Nueva sesión", use_container_width=True):
            reset_conversation()
            st.rerun()

    with center:
        st.markdown(render_chat_html(st.session_state.messages), unsafe_allow_html=True)

        st.markdown('<div class="upload-note">CSV opcional para ejecutar validaciones. Puedes conversar sin cargar archivo.</div>', unsafe_allow_html=True)
        uploaded_file = st.file_uploader("Dataset CSV", type=["csv"])

        df: Optional[pd.DataFrame] = None
        if uploaded_file is not None:
            try:
                df = pd.read_csv(uploaded_file)
                st.markdown(
                    f'<div class="upload-note">Dataset cargado: <b>{html.escape(uploaded_file.name)}</b> · {df.shape[0]} filas x {df.shape[1]} columnas</div>',
                    unsafe_allow_html=True,
                )
            except Exception as exc:
                st.error(f"No se ha podido leer el CSV: {exc}")

        with st.form("chat_form", clear_on_submit=True):
            c1, c2, c3 = st.columns([1, 0.20, 0.20], gap="small")
            with c1:
                user_message = st.text_input("Mensaje", placeholder="Escribe tu mensaje aquí...", label_visibility="collapsed")
            with c2:
                send = st.form_submit_button("➤ ENVIAR", use_container_width=True)
            with c3:
                clear = st.form_submit_button("LIMPIAR", use_container_width=True)

        if clear:
            reset_conversation()
            st.rerun()

        if send and user_message.strip():
            st.session_state.messages.append(
                {"role": "user", "content": user_message, "timestamp": datetime.now().strftime("%H:%M")}
            )

            final_state = app.invoke({"user_message": user_message, "df": df, "model_name": "gpt-4.1-mini"})
            assistant_message = final_state.get("assistant_message", "No he podido generar una respuesta.")

            st.session_state.messages.append(
                {"role": "assistant", "content": assistant_message, "timestamp": datetime.now().strftime("%H:%M")}
            )

            st.session_state.last_report = final_state.get("report")
            st.session_state.last_intent = final_state.get("intent")

            if st.session_state.last_report is not None:
                st.session_state.history.insert(
                    0,
                    ("▰", f"Dataset - {st.session_state.last_report.global_status.value}", datetime.now().strftime("%d/%m/%Y %H:%M")),
                )
                st.session_state.history = st.session_state.history[:4]

            st.rerun()

        # End center column

    with right:
        right_html = (
            '<div class="neon-panel right-panel">'
            '<div class="panel-title">▰ HISTORIAL DE PRUEBAS<br/>DE CALIDAD DE DATOS</div>'
            f'{render_history(st.session_state.history)}'
            f'{render_last_run(st.session_state.last_report)}'
            '<div class="model-card">'
            '<div class="panel-title" style="font-size:15px;margin-bottom:6px;">⌁ MÉTRICAS DE MODELOS</div>'
            '<div class="model-title">'
            '<div style="color:#b84cff;font-weight:800;">Modelo: Clasificador v2.1</div>'
            '<div><span style="color:#00ff85;">●</span> Activo</div>'
            '</div>'
            f'{metric_bar("Accuracy", 92.4)}'
            f'{metric_bar("Precisión", 91.1)}'
            f'{metric_bar("Recall", 90.3)}'
            f'{metric_bar("F1-Score", 90.7)}'
            '</div>'
            f'<div class="school-logo"><img src="data:image/png;base64,{LOGO_B64}" alt="IES Dr. Lluís Simarro" /></div>'
            '</div>'
        )
        st.markdown(right_html, unsafe_allow_html=True)

        if st.session_state.last_report is not None:
            st.download_button(
                label="Descargar JSON",
                data=report_to_json(st.session_state.last_report),
                file_name=f"{st.session_state.last_report.execution_id}_qa_report.json",
                mime="application/json",
                use_container_width=True,
            )


if __name__ == "__main__":
    main()
